            data = f.read()
    except (FileNotFoundError, ProcessLookupError):
        return None
    rp = data.rpartition(")")
    if not rp[1]:
        return None
    tail = rp[2].split()
    try:
        state, pgrp, rss = tail[0], int(tail[2]), int(tail[21])
    except (IndexError, ValueError):
        return None
    comm = rp[0].partition("(")[2]
